import{_ as r,o as a,c as l,a2 as o}from"./chunks/framework.CRFziyHp.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"ops/faq.md","filePath":"ops/faq.md","lastUpdated":1785013113000}'),i={name:"ops/faq.md"};function e(n,t,s,h,d,g){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>汇总站点管理员在后台配置与日常运营中最常遇到的问题及处理思路。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已能登录管理后台（H5）。</li><li>已知自己的管理员类型：超级管理员、平台管理员或区域管理员。</li></ul><hr><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>以下按 <strong>现象</strong> 分类，无需单独配置步骤；请对照跳转至对应功能文档。</p><h3 id="侧栏菜单没有或显示「未解锁-内测中」" tabindex="-1">侧栏菜单没有或显示「未解锁 / 内测中」 <a class="header-anchor" href="#侧栏菜单没有或显示「未解锁-内测中」" aria-label="Permalink to &quot;侧栏菜单没有或显示「未解锁 / 内测中」&quot;">​</a></h3><p><strong>可能原因</strong></p><ol><li><strong>功能模块未授权</strong> — 外卖、AI 中台、UI 管理等需授权后才会出现</li><li><strong>账号权限不足</strong> — 未分配对应菜单权限，侧栏整组隐藏</li><li><strong>商户管理内测</strong> — 外卖 / 骑手在未开通前整组可能不可点</li></ol><p><strong>处理</strong></p><ul><li>超级管理员：<strong>系统设置 → 账号权限</strong> 为账号添加所需权限，或使用 <strong>权限模板</strong> 批量分配</li><li>到 <strong>系统设置 → 我的模块</strong> 确认外卖、AI 中台等是否已开通</li><li>区域管理员只能看到被授权且 <strong>在本区域范围内</strong> 的菜单</li></ul><p>详见 <a href="/guide/admin-access">进入管理后台</a> 与各功能文档前置条件。</p><hr><h3 id="操作保存时提示-403-无权限" tabindex="-1">操作保存时提示 403 / 无权限 <a class="header-anchor" href="#操作保存时提示-403-无权限" aria-label="Permalink to &quot;操作保存时提示 403 / 无权限&quot;">​</a></h3><p><strong>可能原因</strong></p><ul><li>当前账号缺少对应功能的 <strong>修改权限</strong>（如系统配置、区域用户规则）</li><li>区域管理员修改 <strong>其他区域</strong> 数据被拒绝</li><li>站点已关闭「遗留全量权限」，未单独分配权限的管理员默认无法保存</li></ul><p><strong>处理</strong></p><ol><li>让超级管理员在 <strong>系统设置 → 账号权限</strong> 中补充权限</li><li>区域管理员切换页面顶部 <strong>区域筛选</strong> 到管辖区域再保存</li><li>使用 <strong>权限模板</strong> 批量绑定常用角色</li></ol><hr><h3 id="微信登录失败" tabindex="-1">微信登录失败 <a class="header-anchor" href="#微信登录失败" aria-label="Permalink to &quot;微信登录失败&quot;">​</a></h3><p><strong>可能原因</strong></p><ul><li><strong>系统配置 → 微信小程序 / 公众号</strong> Token 测试未通过</li><li><strong>区域管理 → 用户配置</strong> 未开启对应微信登录开关</li><li>公众号 <strong>网页授权域名</strong> 与站点域名不一致</li><li>小程序体验版用户未加入体验成员</li></ul><p><strong>处理</strong></p><ul><li>按 <a href="/features/wechat">微信</a> 文档从 Token 测试到区域开关逐项核对</li></ul><hr><h3 id="支付成功但订单-余额未更新" tabindex="-1">支付成功但订单 / 余额未更新 <a class="header-anchor" href="#支付成功但订单-余额未更新" aria-label="Permalink to &quot;支付成功但订单 / 余额未更新&quot;">​</a></h3><p><strong>可能原因</strong></p><ul><li>微信 / 支付宝 <strong>回调 URL</strong> 未配置或域名错误</li><li>商户 API 证书与平台公钥不匹配</li><li>反向代理缓存了 POST 请求</li></ul><p><strong>处理</strong></p><ul><li>核对回调地址： <ul><li>微信：<code>https://你的域名/api/payment/wx-notify</code></li><li>支付宝：<code>https://你的域名/api/payment/alipay-notify</code></li></ul></li><li>查看 <strong>系统监控 → 系统状态</strong> 与 <strong>财务管理 → 资金交易</strong></li><li>详见 <a href="/features/payment">支付与提现</a></li></ul><hr><h3 id="用户收不到短信-推送-微信通知" tabindex="-1">用户收不到短信 / 推送 / 微信通知 <a class="header-anchor" href="#用户收不到短信-推送-微信通知" aria-label="Permalink to &quot;用户收不到短信 / 推送 / 微信通知&quot;">​</a></h3><p><strong>可能原因</strong></p><ul><li><strong>系统配置 → 腾讯云短信</strong> 未填或模板错误</li><li><strong>通知控制台 → 事件模板</strong> 未勾选对应渠道</li><li>App <strong>Push</strong> 需运维配置 FCM / APNs 环境变量，后台无 Tab</li><li>用户处于 <strong>静默时段</strong> 或未订阅小程序消息</li></ul><p><strong>处理</strong></p><ul><li><a href="/features/sms">短信</a>、<a href="/features/notification">通知与推送</a> 分渠道排查</li><li><strong>通知控制台 → 消息链路追踪</strong> 查看失败原因</li></ul><hr><h3 id="搜索不到新内容" tabindex="-1">搜索不到新内容 <a class="header-anchor" href="#搜索不到新内容" aria-label="Permalink to &quot;搜索不到新内容&quot;">​</a></h3><p><strong>可能原因</strong></p><ul><li>Meilisearch 未启动或密钥不一致</li><li>索引尚未同步</li></ul><p><strong>处理</strong></p><ul><li><strong>系统监控 → 搜索索引</strong> 查看状态</li><li>必要时联系运维启动 <a href="/ops/docker-infra">可选基础设施</a> 并重建索引</li><li>见 <a href="/features/search">搜索与推荐</a></li></ul><hr><h3 id="外卖-跑腿无入口或无人接单" tabindex="-1">外卖 / 跑腿无入口或无人接单 <a class="header-anchor" href="#外卖-跑腿无入口或无人接单" aria-label="Permalink to &quot;外卖 / 跑腿无入口或无人接单&quot;">​</a></h3><p><strong>可能原因</strong></p><ul><li><strong>区域外卖配置 / 跑腿区域配置</strong> 未启用</li><li><strong>UI TabBar</strong> 未添加 Tab</li><li><strong>骑手审核</strong> 通过人数不足或骑手未上线</li></ul><p><strong>处理</strong></p><ul><li><a href="/features/takeaway">外卖</a>、<a href="/features/errand">跑腿</a>、<a href="/features/rider">骑手</a> 文档串联排查</li></ul><hr><h3 id="无法进入管理后台" tabindex="-1">无法进入管理后台 <a class="header-anchor" href="#无法进入管理后台" aria-label="Permalink to &quot;无法进入管理后台&quot;">​</a></h3><p><strong>可能原因</strong></p><ul><li>非 H5 环境（管理端仅浏览器 H5）</li><li>账号类型不是超级管理员 / 平台管理员 / 区域管理员</li><li>未登录或登录过期</li></ul><p><strong>处理</strong></p><ul><li>使用 Chrome 等浏览器打开 <strong><code>https://你的域名/pages_admin/index/index</code></strong>（不是文档站地址）</li><li>确认账号类型；普通用户无后台入口</li></ul><hr><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>检查菜单</th></tr></thead><tbody><tr><td>某区域功能与其他区域不一致</td><td>是否只改了「平台默认」未改该区域行</td></tr><tr><td>区域管理员看不到数据</td><td><strong>系统设置 → 账号权限</strong> 中该账号的管辖区域是否包含目标区域</td></tr><tr><td>关闭某区域私信</td><td><strong>区域列表</strong> 编辑区域</td></tr></tbody></table><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><p>解决任一问题后，用 <strong>最小复现路径</strong> 再测一次（如：单用户微信登录、单笔支付、单条搜索），并在对应监控 / 流水菜单确认记录正常。</p><h2 id="常见问题-补充" tabindex="-1">常见问题（补充） <a class="header-anchor" href="#常见问题-补充" aria-label="Permalink to &quot;常见问题（补充）&quot;">​</a></h2><p><strong>改了配置客户端仍旧样</strong></p><ul><li>客户端缓存：杀进程重进；UI 配置需匹配 <strong>同一区域</strong></li><li>部分系统配置保存后立即生效，微信 Token 类需点「获取 Token」验证</li></ul><p><strong>找谁处理</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>负责方</th></tr></thead><tbody><tr><td>菜单、区域规则、活动配置</td><td>站点管理员</td></tr><tr><td>服务器、Docker、环境变量、备份</td><td>运维</td></tr><tr><td>授权模块开通</td><td>授权 / 商务</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/ops/checklist">上线检查清单</a></li><li><a href="/ops/monitoring">系统监控入口</a></li><li><a href="/config/system-settings">系统配置总览</a></li></ul>',68)])])}const c=r(i,[["render",e]]);export{p as __pageData,c as default};
